import Foundation

extension Waypoint {
    /// Great-circle distance to `other`, in meters (haversine, mean Earth radius).
    func distance(to other: Waypoint) -> Double {
        let r = 6_371_000.0
        let dLat = (other.latitude - latitude) * .pi / 180
        let dLon = (other.longitude - longitude) * .pi / 180
        let a = sin(dLat / 2) * sin(dLat / 2)
            + cos(latitude) * cos(other.latitude) * sin(dLon / 2) * sin(dLon / 2)
        return 2 * r * asin(min(1, sqrt(a)))
    }
}

import XCTest
@testable import TrailmixKit

final class WaypointDistanceTests: XCTestCase {
    func testZeroDistance() {
        let p = Waypoint(latitude: 47.6, longitude: -122.3)
        XCTAssertEqual(p.distance(to: p), 0, accuracy: 0.001)
    }

    func testSeattleToPortland() {
        let sea = Waypoint(latitude: 47.6062, longitude: -122.3321)
        let pdx = Waypoint(latitude: 45.5152, longitude: -122.6784)
        XCTAssertEqual(sea.distance(to: pdx), 233_600, accuracy: 1_000)
    }

    func testLondonToParis() {
        let lon = Waypoint(latitude: 51.5074, longitude: -0.1278)
        let par = Waypoint(latitude: 48.8566, longitude: 2.3522)
        XCTAssertEqual(lon.distance(to: par), 343_500, accuracy: 1_000)
    }

    func testAcrossEquator() {
        let a = Waypoint(latitude: 1, longitude: 30)
        let b = Waypoint(latitude: -1, longitude: 30)
        XCTAssertEqual(a.distance(to: b), 222_390, accuracy: 500)
    }
}

